"""Focused command-center styling layered over Streamlit's accessible controls."""

from __future__ import annotations


def get_command_center_css() -> str:
    """Return responsive, stateful styling for the operations shell."""
    return """<style>
    /* Tokens map to the active theme's CSS variables (src/ui/theme.py) so light
       AND dark mode stay consistent. Previously this block hard-coded light
       colours with !important, which fought the theme layer and produced mixed
       light/dark glitching surfaces. */
    :root { --ops-ink:var(--heading); --ops-slate:var(--muted); --ops-surface:var(--panel); --ops-ground:var(--bg); --ops-line:var(--line); --ops-teal:var(--green); --ops-teal-soft:var(--green-soft); --ops-alert:var(--red); --ops-alert-soft:var(--red-soft); --ops-radius:14px; }
    .block-container { max-width:1480px!important; padding:1.5rem 2rem 3rem!important; }[data-testid="stSidebar"] { border-right:1px solid var(--ops-line)!important; }[data-testid="stSidebar"] > div:first-child { padding:1.25rem .75rem!important; }
    .ops-sidebar-brand { display:flex; align-items:center; gap:.75rem; padding:.45rem .5rem 1rem; border-bottom:1px solid var(--ops-line); }.ops-brand-mark { display:grid; place-items:center; width:34px; height:34px; color:var(--ops-teal); background:var(--ops-teal-soft); border-radius:10px; }.ops-brand-mark svg { width:21px; height:21px; }.ops-sidebar-brand strong { display:block; color:var(--ops-ink); font-size:.95rem; letter-spacing:-.02em; }.ops-sidebar-brand span { display:block; margin-top:2px; color:var(--ops-slate); font-size:.65rem; letter-spacing:.09em; font-weight:700; }.ops-sidebar-context { display:flex; align-items:center; gap:.45rem; padding:.85rem .5rem .45rem; color:var(--ops-slate); font-size:.76rem; }.ops-dot { width:7px; height:7px; border-radius:999px; background:var(--ops-teal); }
    .ops-header { display:flex; justify-content:space-between; align-items:center; gap:1rem; min-height:42px; padding-bottom:1.15rem; border-bottom:1px solid var(--ops-line); margin-bottom:1.75rem; }.ops-header-title span { display:block; color:var(--ops-ink); font-size:.92rem; font-weight:750; }.ops-header-title small { color:var(--ops-slate); font-size:.75rem; }.ops-header-meta { display:flex; align-items:center; gap:.65rem; font-size:.75rem; }.ops-model { color:var(--ops-slate); max-width:20rem; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }.ops-health { display:inline-flex; align-items:center; gap:.4rem; border-radius:999px; padding:.38rem .65rem; font-weight:700; }.ops-health i { width:7px; height:7px; border-radius:999px; background:currentColor; }.ops-health.is-ready { color:var(--ops-teal); background:var(--ops-teal-soft); }.ops-health.is-attention { color:var(--ops-alert); background:var(--ops-alert-soft); }
    .ops-task-header,.ops-page-heading { display:flex; justify-content:space-between; align-items:flex-start; gap:1.25rem; margin:0 0 1.5rem; }.ops-task-header h1,.ops-page-heading h1 { margin:0!important; color:var(--ops-ink)!important; font-size:clamp(1.65rem,3vw,2.15rem)!important; letter-spacing:-.04em!important; line-height:1.08!important; }.ops-task-header p,.ops-page-heading p { max-width:48rem; margin:.5rem 0 0; color:var(--ops-slate); line-height:1.55; }.ops-context-status,.ops-page-context { color:var(--ops-teal); background:var(--ops-teal-soft); border-radius:999px; padding:.42rem .7rem; font-size:.75rem; font-weight:700; white-space:nowrap; }.ops-page-context { display:flex; align-items:center; gap:.65rem; }.ops-page-context small { color:var(--ops-slate); font-weight:600; }
    .ops-observation-strip { display:flex; justify-content:space-between; gap:1rem; align-items:center; padding:.85rem 1rem; margin:.75rem 0 1rem; background:var(--ops-surface); border:1px solid var(--ops-line); border-radius:var(--ops-radius); }.ops-state { display:inline-flex; border-radius:999px; padding:.28rem .55rem; font-size:.72rem; font-weight:750; }.ops-state.ready { color:var(--ops-teal); background:var(--ops-teal-soft); }.ops-state.attention { color:var(--ops-alert); background:var(--ops-alert-soft); }.ops-state.neutral { color:var(--ops-slate); background:var(--hover); }.ops-observation-detail { margin-left:.6rem; color:var(--ops-slate); font-size:.78rem; }.ops-observation-meta { color:var(--ops-slate); font-size:.74rem; font-variant-numeric:tabular-nums; white-space:nowrap; }
    .metric-card,.panel { border-color:var(--ops-line)!important; border-radius:var(--ops-radius)!important; box-shadow:none!important; }.metric-card:hover,.panel:hover { box-shadow:none!important; transform:none!important; }.metric-card { background:var(--ops-surface)!important; padding:1rem 1.1rem!important; }.metric-main strong { color:var(--ops-ink)!important; font-variant-numeric:tabular-nums; }.metric-icon { display:none!important; }button[kind="primary"], [data-testid="stButton"] button[kind="primary"] { background:var(--ops-teal)!important; border-color:var(--ops-teal)!important; min-height:2.45rem!important; }[data-testid="stButton"] button { border-radius:10px!important; }[data-testid="stRadio"] label { border-radius:9px!important; }[data-testid="stRadio"] label:hover { background:var(--hover)!important; }[data-testid="stDataFrame"] { border:1px solid var(--ops-line); border-radius:var(--ops-radius); overflow:hidden; }:focus-visible { outline:3px solid rgba(8,125,104,.35)!important; outline-offset:2px!important; }
    @media (max-width:800px) { .block-container { padding:1rem 1rem 2rem!important; }.ops-header,.ops-task-header,.ops-page-heading,.ops-observation-strip { align-items:flex-start; flex-direction:column; }.ops-header-meta { width:100%; justify-content:space-between; }.ops-model { max-width:12rem; }.ops-observation-detail { display:block; margin:.45rem 0 0; }.ops-observation-meta { white-space:normal; }.ops-task-header h1,.ops-page-heading h1 { font-size:1.5rem!important; } }
    /* U2 skeleton loading: theme-aware shimmer used while camera/frames initialize. */
    .ops-skeleton { position:relative; overflow:hidden; background:var(--ops-surface); border:1px dashed var(--ops-line); border-radius:var(--ops-radius); }
    .ops-skeleton::after { content:""; position:absolute; inset:0; transform:translateX(-100%); background:linear-gradient(90deg, transparent, var(--hover), transparent); animation:ops-shimmer 1.6s infinite; }
    @keyframes ops-shimmer { 100% { transform:translateX(100%); } }
    @media (prefers-reduced-motion:reduce) { .ops-skeleton::after { animation:none; } }
    .ops-skeleton-label { position:absolute; inset:0; display:grid; place-items:center; text-align:center; z-index:1; }
    .ops-skeleton-label strong { display:block; color:var(--secondary); font-size:13px; letter-spacing:.08em; text-transform:uppercase; }
    .ops-skeleton-label span { display:block; margin-top:6px; color:var(--ops-slate); font-size:11.5px; }
    /* U7 perf chip: compact FPS/latency indicator overlaid near viewports. */
    .ops-perf-chip { display:inline-flex; align-items:center; gap:.45rem; padding:.3rem .6rem; border-radius:999px; background:var(--ops-surface); border:1px solid var(--ops-line); color:var(--ops-teal); font-size:11px; font-family:monospace; font-weight:700; }
    /* U4 accessibility: visually hidden but screen-reader exposed text. */
    .sr-only { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0 0 0 0); white-space:nowrap; border:0; }
    </style>"""
